import tempfile

from . import bip_config
from . import bts_info
from . import mapping_config
from . import aashell
from .tools import python_log
from contextlib import contextmanager
from taf.transport.ssh.connection import connect
import logging
import os
import time


RUNNING_SCRIPTS = None
TARGET_FILE_NAME = "bip_trace_script.pcap"
logger = logging.getLogger()


@contextmanager
def connect_to_lmp(gnb_id):
    """
    Context manager for connecting to the lmp of the gnb
    :param gnb_id: The gnb_id of tl config for the gnb to access to
    """
    lmp_connection_details = bip_config.get_lmp_connection()
    ssh_connection = connect(hostname=lmp_connection_details['host'],
                             username=lmp_connection_details['user'],
                             password=lmp_connection_details['password'])

    yield ssh_connection

    ssh_connection.disconnect()


@python_log
def find_mirror_scripts():
    """
    searches for all the scripts inside the folder "mirror_scripts"
    within the location of the installation path of this module
    """
    module_path, _ = os.path.split(os.path.realpath(__file__))

    local_mirror_script_path = os.path.join(module_path, 'mirror_scripts')
    file_name_list = os.listdir(local_mirror_script_path)
    mirror_scripts = [os.path.join(local_mirror_script_path, file_name) for file_name in file_name_list]

    return mirror_scripts


@python_log
def upload_mirror_scripts(lmp_connection, script_files, remote_path="/tmp"):
    """
    uploads the list of script files to the remote system/bts system module within the given path
    """
    fp = lmp_connection.files

    remote_files = []
    for script in script_files:
        _, script_file_name = os.path.split(script)
        remote_file = os.path.join(remote_path, script_file_name)
        fp.put(script, remote_file)
        remote_files.append(remote_file)
    return remote_files


@python_log
def wait_for_tcpdump_running(lmp_connection):
    for _ in range(30):
        ret = lmp_connection.execute(command='ps -ef |grep tcpdump_L2L1_bip_filtering |grep -v grep')
        logger.info('PS Grep filtered for tcpdump: [{}]'.format(ret))
        if ret:
            return
        time.sleep(1)


@python_log
def execute_the_mirror_script_in_background(lmp_connection, mirror_script, optional=None):
    if optional:
        cmd = 'cd /tmp; nohup sh {} {} 1> /tmp/mirror_stdout.txt 2>&1 &'.format(mirror_script, optional.strip('"'))
    else:
        cmd = 'cd /tmp; nohup sh {} 1> /tmp/mirror_stdout.txt 2>&1 &'.format(mirror_script)

    logger.info('Running Command: {}'.format(cmd))
    lmp_connection.send_command(command=cmd)
    wait_for_tcpdump_running(lmp_connection)


@python_log
def kill_tcpdump_for_l2l1(lmp_connection, system_module, baseband_modules):
    kill_cmd = "ps -ef |grep tcpdump |grep tcpdump_L2L1_bip |grep -v grep |awk '{print $2}'|xargs kill -INT"
    if system_module == "ASIM" or (system_module == "ASIL" and 'ABIO' in baseband_modules):
        kill_cmd = '''bsh 1:0 "ps -ef|grep -v grep  |pgrep tcpdump |xargs kill -2"'''
    if system_module == "ASIL" and 'ABIO' not in baseband_modules:
        kill_cmd = "ps -ef |grep tcpdump |grep tcpdump_L2L1_bip |grep -v grep |awk '{print $2}'|xargs kill -15"

    output = lmp_connection.execute(command=kill_cmd)
    logger.info("the kill command: [{}]".format(kill_cmd))
    logger.info("Output of the kill command: [{}]".format(output))
    for i in range(300):
        ps_cmd = "ps -ef |grep gnbMirroring.sh |grep -v grep |awk '{print $2}'"
        result = lmp_connection.execute(command=ps_cmd)
        logger.info("the result: [{}]".format(result))
        if result:
            time.sleep(1)


@python_log
def download_tcpdump_result_asim(lmp_connection, target_dir):
    cmd = "bsh 1:0 'ls /tmp/tcpdump_L2L1_bip*'"
    logger.info("download command: [{}]".format(cmd))
    pcap_files = lmp_connection.execute(command=cmd)
    logger.info(pcap_files)
    pcap_files = pcap_files.split("\r\n")[:-1]
    logger.info("download files: [{}]".format(pcap_files))
    for pcap_file in pcap_files:
        cmd = "bget 1:0 {} /tmp".format(pcap_file)
        logger.info("bget command: [{}]".format(cmd))
        lmp_connection.execute(command=cmd)
        rm_asim_bip_trace = "bsh 1:0 rm {}".format(pcap_file)
        logger.info("rm command: [{}]".format(rm_asim_bip_trace))
        lmp_connection.execute(command=rm_asim_bip_trace)

    sftp = lmp_connection.files
    files = sftp.listdir("/tmp/")

    logger.debug("Returned Files: " + str(files))
    bip_traces = [filename for filename in files if filename.startswith("tcpdump_L2L1_bip_filtering")]

    local_bip_traces = []
    for bip_trace in bip_traces:
        remote_bip_trace = "/tmp/" + bip_trace
        downloaded_bip_trace = os.path.join(target_dir, bip_trace)
        sftp.get(remote_bip_trace, downloaded_bip_trace)
        lmp_connection.execute(command='rm {}'.format(remote_bip_trace))
        local_bip_traces.append(downloaded_bip_trace)

    sftp.get("/tmp/mirror_stdout.txt", os.path.join(target_dir, "mirror_stdout.txt"))
    cmd_output = lmp_connection.execute(command='cat /tmp/mirror_stdout.txt')
    logger.info(cmd_output)
    if not local_bip_traces:
        logger.warning("No recorded bip traces have been found on BTS!")
    return local_bip_traces


@python_log
def download_tcpdump_result(lmp_connection, target_dir):
    sftp = lmp_connection.files
    files = sftp.listdir("/tmp/")

    logger.debug("Returned Files: " + str(files))
    bip_traces = [filename for filename in files if filename.startswith("tcpdump_L2L1_bip_filtering")]

    local_bip_traces = []
    for bip_trace in bip_traces:
        remote_bip_trace = os.path.join("/tmp", bip_trace)
        downloaded_bip_trace = os.path.join(target_dir, bip_trace)
        sftp.get(remote_bip_trace, downloaded_bip_trace)
        lmp_connection.execute(command='rm {}'.format(remote_bip_trace))
        local_bip_traces.append(downloaded_bip_trace)

    sftp.get("/tmp/mirror_stdout.txt", os.path.join(target_dir, "mirror_stdout.txt"))
    cmd_output = lmp_connection.execute(command='cat /tmp/mirror_stdout.txt')
    logger.info(cmd_output)
    if not local_bip_traces:
        logger.warning("No recorded bip traces have been found on BTS!")
    return local_bip_traces


@python_log
def execute_the_mirror_script(lmp_connection, remote_scripts, start_script=None, optional=None):
    for script in remote_scripts:
        output = lmp_connection.execute(command='chmod 750 {}'.format(script))
        logger.info('Output of "chmod 755 {}": [{}]'.format(script, output))

    try:
        if start_script is None:
            mirror_main = [script for script in remote_scripts if script.endswith("main.sh")][0]
        else:
            mirror_main = [script for script in remote_scripts if script.endswith(start_script)][0]

    except IndexError:
        raise AssertionError("Mirror script (default main.sh) was not found!")

    execute_the_mirror_script_in_background(lmp_connection, mirror_main, optional=optional)


@python_log
def mirror_and_start_tcpdump(gnb_id, script=None, optional=None):
    mirror_scripts = find_mirror_scripts()

    optional = bip_config.BIP_CONFIG[gnb_id].get('script_parameters')
    with connect_to_lmp(gnb_id) as lmp_connection:
        remote_files = upload_mirror_scripts(lmp_connection, mirror_scripts, remote_path="/tmp")
        execute_the_mirror_script(lmp_connection, remote_files, script, optional)


@python_log
def start(gnb_id, optional=None):
    system_module = bts_info.get_system_module(gnb_id)
    baseband_modules = bts_info.get_baseband_modules(gnb_id)
    l1type = aashell.get_l1_type(gnb_id)
    script = mapping_config.get_bip_script(l1_type=l1type,
                                           gnb_common_unit=system_module,
                                           gnb_capacity_unit=baseband_modules)
    mirror_and_start_tcpdump(gnb_id, script, optional)


@python_log
def stop(gnb_id):
    with connect_to_lmp(gnb_id) as lmp_connection:
        system_module = bts_info.get_system_module(gnb_id)
        baseband_modules = bts_info.get_baseband_modules(gnb_id)
        kill_tcpdump_for_l2l1(lmp_connection, system_module, baseband_modules)


@python_log
def collect(gnb_id, target_dir=tempfile.gettempdir()):
    with connect_to_lmp(gnb_id) as lmp_connection:
        system_module = bts_info.get_system_module(gnb_id)
        baseband_modules = bts_info.get_baseband_modules(gnb_id)
        if system_module == "ASIM" or (system_module == "ASIL" and 'ABIO' in baseband_modules):
            downloaded_pcap_files = download_tcpdump_result_asim(lmp_connection, target_dir)
        else:
            downloaded_pcap_files = download_tcpdump_result(lmp_connection, target_dir)

    if type(downloaded_pcap_files) is list:
        return sorted(downloaded_pcap_files)
    else:
        return [downloaded_pcap_files]
